CREATE TABLE users (id int PRIMARY KEY, name text, email text);
CREATE TABLE categories (id int PRIMARY KEY, name text);
CREATE TABLE products (id int PRIMARY KEY, unit_id int, category_id int, name text, brand text, unit_of_measure text, price numeric, active boolean);
CREATE TABLE stock (product_id int, quantity numeric, min_quantity numeric);
CREATE TABLE orders (id int PRIMARY KEY, unit_id int, client_id int, order_date timestamptz, scheduled_delivery_date timestamptz, status text, subtotal numeric, discount_amount numeric, delivery_fee numeric, total_amount numeric, checkout_id text, delivery_person_id int);
CREATE TABLE order_items (order_id int, product_id int, product_snapshot jsonb, quantity numeric, unit_price numeric);
CREATE TABLE payments (order_id int, status text, method text, refunded_amount numeric, fee_amount numeric, payment_date timestamptz, refund_status text);
CREATE TABLE delivery_settlements (order_id int, delivery_person_id int, amount numeric, paid_at timestamptz, reference text);
CREATE TABLE payment_refunds (unit_id int, order_id int, payment_id text, status text);
CREATE TABLE payment_transactions (id text, unit_id int, reference text);
CREATE TABLE expenses (id int, unit_id int, "supplierName" text, type text, amount numeric, discount numeric, "paidAmount" numeric, "paidAt" text, "postedAt" text, "paymentMethod" text);
CREATE TABLE coupons (id int, unit_id int, code text, name text, type text, discount_type text, discount_amount numeric, starts_at timestamptz, expires_at timestamptz, active boolean, created_at timestamptz);
CREATE TABLE coupon_units (coupon_id int, unit_id int);
CREATE TABLE coupon_redemptions (coupon_id int, unit_id int, discount_amount numeric, status text);
CREATE TABLE promotions (id int, unit_id int, product_id int, title text, starts_at timestamptz, ends_at timestamptz, discount_percentage numeric, promotional_price numeric, active boolean, created_at timestamptz);
CREATE TABLE support_tickets (id int, unit_id int, user_id int, subject text, category text, priority text, status text, created_at timestamptz, closed_at timestamptz);
CREATE TABLE reviews (id int, unit_id int, order_id int, product_id int, rating int, comment text, created_at timestamptz);
CREATE TABLE user_units (id int, unit_id int, user_id int, local_role text, status text);
CREATE TABLE delivery_persons (id int, user_id int, status text, vehicle text, is_online boolean);
ALTER TABLE orders ADD COLUMN delivery_type text DEFAULT 'DELIVERY';
